	@Test
	void localParentRetainsObjectiveResidualFromSelectedChildEvent() {
		Filter filter = new Filter(input(),
				new ValueConstant(SimpleValueFactory.getInstance().createLiteral(true)));
		PackedCostModel model = new PackedCostModel() {

			@Override
			public double estimateRows(PackedQueryView query, int relationId) {
				return Double.NaN;
			}

			@Override
			public PackedCostSession openSession(PackedQueryView query) {
				return new PackedCostSession() {

					@Override
					public void estimateLeaf(int relationId, PackedCostContext context, PackedCostEstimate output) {
						if (!query.isStatementPattern(relationId)) {
							return;
						}
						output.setRows(1.0d, 10.0d);
						output.setInclusivePhysicalCost(10.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d,
								0.0d, 0.0d);
						output.putPlannedDoubleMetric("testObjectiveResidual", 90.0d);
					}

					@Override
					public void appendFactor(int relationId, PackedCostContext context, PackedCostEstimate output) {
						estimateLeaf(relationId, context, output);
					}

					@Override
					public void refineOperator(int relationId, PackedCostContext context, PackedCostEstimate output) {
						if (query.isFilter(relationId)) {
							output.setLocalPhysicalCost(1.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d,
									0.0d, 0.0d);
						}
					}

					@Override
					public double objectiveScore(PackedCostEstimate estimate) {
						double residual = estimate.plannedDoubleMetrics()
								.getOrDefault("testObjectiveResidual", 0.0d);
						return estimate.workRows() + residual;
					}
				};
			}
		};

		PackedPlanningResult result = PackedCascadesPlanner.optimize(filter, OptimizationGoal.root(), model);

		assertEquals(101.0d, result.totalCost(),
				"a parent-local vector must not replace an objective component certified by its child winner");
	}

	@Test
	void disconnectedComponentEvidenceIsNotStampedAsWholeJoinEvidence() {
		SimpleValueFactory values = SimpleValueFactory.getInstance();
		StatementPattern left = new StatementPattern(Var.of("left"),
				Var.of("leftPredicate", values.createIRI("urn:left")), Var.of("leftValue"));
		StatementPattern right = new StatementPattern(Var.of("right"),
				Var.of("rightPredicate", values.createIRI("urn:right")), Var.of("rightValue"));
		int[] joinEvents = new int[2];
		PackedCostModel model = new PackedCostModel() {

			@Override
			public double estimateRows(PackedQueryView query, int relationId) {
				return Double.NaN;
			}

			@Override
			public PackedCostSession openSession(PackedQueryView query) {
				return new PackedCostSession() {

					@Override
					public void estimateLeaf(int relationId, PackedCostContext context, PackedCostEstimate output) {
						output.setRows(2.0d, 2.0d);
						output.setEvidenceStateId(relationId);
						output.setEvidenceGuarantee(EvidenceGuarantee.DATABASE_EXACT);
						output.setEvidenceDisposition(FrontierStateDisposition.COMPOSABLE_PAYLOAD);
					}

					@Override
					public void appendFactor(int relationId, PackedCostContext context, PackedCostEstimate output) {
						output.setComponentRows(2.0d, 2.0d);
						output.setEvidenceStateId(relationId);
						output.setEvidenceGuarantee(EvidenceGuarantee.DATABASE_EXACT);
						output.setEvidenceDisposition(FrontierStateDisposition.COMPOSABLE_PAYLOAD);
					}

					@Override
					public void refineOperator(int relationId, PackedCostContext context, PackedCostEstimate output) {
					}

					@Override
					public void refineIntermediateJoin(PackedCostContext context, PackedCostEstimate output) {
						if (context.leftInputEvidenceStateId() == 0 || context.rightInputEvidenceStateId() == 0
								|| Double.compare(output.outputRows(), 4.0d) != 0) {
							return;
						}
						joinEvents[0]++;
						if (context.evidenceStateId() != 0) {
							joinEvents[1]++;
						}
					}
				};
			}
		};

		PackedCascadesPlanner.optimize(new Join(left, right), OptimizationGoal.root(), model);

		assertTrue(joinEvents[0] > 0, "the disconnected join must reach physical candidate costing");
		assertEquals(0, joinEvents[1],
				"component evidence describes only the appended factor and must not suppress child-state composition");
	}

	@Test
	void metadataAndContextualCopiesPreserveExplicitPhysicalCostSemantics() throws Exception {
		PackedCostEstimate source = new PackedCostEstimate();
		source.setContextualRows(13.0d, 1.0d);
		source.setInclusivePhysicalCost(2.0d, 3.0d, 5.0d, 7.0d, 11.0d, 13.0d, 17.0d, 19.0d, 23.0d);
		source.setDependentSubqueriesCosted(true);
		PackedCostEstimate.class
				.getMethod("setEvidenceDisposition", FrontierStateDisposition.class)
				.invoke(source, FrontierStateDisposition.OPAQUE_BOUNDARY);

		PackedPhysicalMetadataArena arena = new PackedPhysicalMetadataArena(1);
		int metadataId = arena.append(source, 1.0d, 1.0d);

		assertEquals("INCLUSIVE", arenaValue(arena, metadataId, "costScope").toString());
		assertEquals(true, arenaValue(arena, metadataId, "hasExplicitPhysicalCost"));
		assertEquals(true, arenaValue(arena, metadataId, "dependentSubqueriesCosted"));
		assertEquals(FrontierStateDisposition.OPAQUE_BOUNDARY,
				arenaValue(arena, metadataId, "evidenceDisposition"));

		PackedCostEstimate copy = new PackedCostEstimate();
		Method copyEstimate = PackedJoinEnumerator.class.getDeclaredMethod("copyEstimate",
				PackedCostEstimate.class, PackedCostEstimate.class);
		copyEstimate.setAccessible(true);
		copyEstimate.invoke(null, source, copy);

		assertEquals(PackedCostEstimate.CostScope.INCLUSIVE, copy.costScope());
		assertEquals(2.0d, copy.sequentialRows());
		assertEquals(3.0d, copy.randomSeeks());
		assertEquals(23.0d, copy.peakMemoryRows());
		assertEquals(true, copy.hasExplicitPhysicalCost());
		assertEquals(true, copy.dependentSubqueriesCosted());
		assertEquals(FrontierStateDisposition.OPAQUE_BOUNDARY,
				PackedCostEstimate.class.getMethod("evidenceDisposition").invoke(copy));
	}

	@Test
	void compactMetadataColumnsPreserveRowsAcrossLateRichEstimate() {
		PackedSearchBudget budget = new PackedSearchBudget(PackedPlannerLimits.unbounded());
		PackedPhysicalMetadataArena arena = new PackedPhysicalMetadataArena(0, budget);
		PackedCostEstimate scalarBefore = new PackedCostEstimate();
		scalarBefore.setRows(3.0d, 5.0d);
		int scalarBeforeId = arena.append(scalarBefore, 1.0d, 1.0d);

		PackedCostEstimate rich = new PackedCostEstimate();
		rich.setRows(7.0d, 11.0d);
		rich.setInclusivePhysicalCost(2.0d, 3.0d, 5.0d, 7.0d, 11.0d, 13.0d, 17.0d, 19.0d,
				23.0d);
		rich.setObjectiveInterval(50.0d, 55.0d, 60.0d);
		rich.setAccess(3, 1, 2, 17.0d, 4.0d, "spoc", "frontier", "bound-prefix");
		rich.setEvidenceStateId(41);
		rich.setEvidenceGuarantee(EvidenceGuarantee.DATABASE_EXACT);
		int richId = arena.append(rich, 1.0d, 1.0d);

		PackedCostEstimate scalarAfter = new PackedCostEstimate();
		scalarAfter.setRows(13.0d, 29.0d);
		scalarAfter.putPlannedStringMetric("providerTag", "late");
		int scalarAfterId = arena.append(scalarAfter, 1.0d, 1.0d);
		arena.addRuleProofMask(scalarAfterId, 8L);
		PackedCostEstimate overriddenScope = new PackedCostEstimate();
		overriddenScope.setRows(31.0d, 37.0d);
		overriddenScope.putPlannedStringMetric("plannedCostScope", "provider-defined");
		int overriddenScopeId = arena.append(overriddenScope, 1.0d, 1.0d);

		assertEquals(5.0d, arena.sequentialRows(scalarBeforeId));
		assertEquals(0.0d, arena.randomSeeks(scalarBeforeId));
		assertEquals(5.0d, arena.objectivePointCost(scalarBeforeId));
		assertTrue(Double.isNaN(arena.accessRows(scalarBeforeId)));
		assertEquals(1.0d, arena.invocations(scalarBeforeId));
		assertEquals(1, arena.plannedStringMetricCount(scalarBeforeId));
		assertEquals("plannedCostScope", arena.plannedStringMetricName(scalarBeforeId, 0));
		assertEquals("local", arena.plannedStringMetricValue(scalarBeforeId, 0));

		assertEquals(2.0d, arena.sequentialRows(richId));
		assertEquals(3.0d, arena.randomSeeks(richId));
		assertEquals(55.0d, arena.objectivePointCost(richId));
		assertEquals(17.0d, arena.accessRows(richId));
		assertEquals(4.0d, arena.invocations(richId));
		assertEquals(41, arena.evidenceStateId(richId));
		assertEquals(EvidenceGuarantee.DATABASE_EXACT, arena.evidenceGuarantee(richId));
		assertEquals("spoc", arena.indexName(richId));
		assertEquals("inclusive", arena.plannedStringMetricValue(richId, 0));

		assertEquals(29.0d, arena.sequentialRows(scalarAfterId));
		assertEquals(0.0d, arena.randomSeeks(scalarAfterId));
		assertEquals(29.0d, arena.objectiveUpperBound(scalarAfterId));
		assertTrue(Double.isNaN(arena.accessRows(scalarAfterId)));
		assertEquals(1.0d, arena.invocations(scalarAfterId));
		assertEquals(8L, arena.ruleProofMask(scalarAfterId));
		assertEquals(2, arena.plannedStringMetricCount(scalarAfterId));
		assertEquals("plannedCostScope", arena.plannedStringMetricName(scalarAfterId, 0));
		assertEquals("local", arena.plannedStringMetricValue(scalarAfterId, 0));
		assertEquals("providerTag", arena.plannedStringMetricName(scalarAfterId, 1));
		assertEquals("late", arena.plannedStringMetricValue(scalarAfterId, 1));

		assertEquals(1, arena.plannedStringMetricCount(overriddenScopeId));
		assertEquals("plannedCostScope", arena.plannedStringMetricName(overriddenScopeId, 0));
		assertEquals("provider-defined", arena.plannedStringMetricValue(overriddenScopeId, 0));
		assertEquals(PackedPhysicalMetadataArena.requiredBytesForCapacity(8, 8, 4), budget.retainedBytes(),
				"virtual metrics must retain the same logical byte accounting as materialized metrics");
	}

	@Test
	void genericDependentSubqueryCostIsChargedToOwningFilter() {
		SimpleValueFactory values = SimpleValueFactory.getInstance();
		StatementPattern outer = new StatementPattern(Var.of("subject"),
				Var.of("outerPredicate", values.createIRI("urn:outer")), Var.of("outerValue"));
		StatementPattern dependent = new StatementPattern(Var.of("subject"),
				Var.of("dependentPredicate", values.createIRI("urn:dependent")), Var.of("dependentValue"));
		Filter filter = new Filter(outer,
				new Or(new Exists(dependent), new ValueConstant(values.createLiteral(false))));
		PackedCostModel model = new PackedCostModel() {

			@Override
			public double estimateRows(PackedQueryView query, int relationId) {
				return Double.NaN;
			}

			@Override
			public PackedCostSession openSession(PackedQueryView query) {
				return new PackedCostSession() {

					@Override
					public void estimateLeaf(int relationId, PackedCostContext context, PackedCostEstimate output) {
						if (!query.isStatementPattern(relationId)) {
							return;
						}
						boolean dependentPattern = query.materializeRelation(relationId).equals(dependent);
						output.setRows(dependentPattern ? 1.0d : 10.0d, dependentPattern ? 100.0d : 10.0d);
						output.setInclusivePhysicalCost(dependentPattern ? 100.0d : 10.0d, 0.0d, 0.0d, 0.0d,
								0.0d, 0.0d, 0.0d, 0.0d, 0.0d);
					}

					@Override
					public void appendFactor(int relationId, PackedCostContext context, PackedCostEstimate output) {
						estimateLeaf(relationId, context, output);
					}

					@Override
					public void refineOperator(int relationId, PackedCostContext context, PackedCostEstimate output) {
						if (query.isFilter(relationId)) {
							output.setLocalPhysicalCost(1.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d);
						}
					}
				};
			}
		};

		String previous = System.getProperty(
				PackedDependentSubqueryCosting.CORRELATED_DEPENDENT_INVOCATIONS_PROPERTY);
		System.setProperty(PackedDependentSubqueryCosting.CORRELATED_DEPENDENT_INVOCATIONS_PROPERTY, "true");
		try {
			PackedPlanningResult result = PackedCascadesPlanner.optimize(filter, OptimizationGoal.root(), model);

			// outer scan (10) + filter refinement (1) + dependent startup (1) once + ten invocations of the
			// non-startup child work (99). Startup belongs to the physical recipe, not to every rebind.
			assertEquals(1_002.0d, result.totalCost(), result.selectedPlan()::toString);
		} finally {
			if (previous == null) {
				System.clearProperty(PackedDependentSubqueryCosting.CORRELATED_DEPENDENT_INVOCATIONS_PROPERTY);
			} else {
				System.setProperty(PackedDependentSubqueryCosting.CORRELATED_DEPENDENT_INVOCATIONS_PROPERTY,
						previous);
			}
		}
	}

